INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'basic', 'multiple_choice', 'What is the general purpose of a ''condenser'' in the carding process for certain fiber types (e.g., in woolen carding)?', '["To divide the carded fiber web into narrow strips and rub/condense them into continuous rovings directly off the card","To dye the fiber immediately after carding","To wind finished yarn onto cones","To open raw fiber bales before carding"]'::jsonb, 'To divide the carded fiber web into narrow strips and rub/condense them into continuous rovings directly off the card', 'In woolen-system carding, a condenser (tape condenser) divides the wide carded web into narrow strips and rubs them into rovings directly, differing from the cotton system''s separate drawing/roving steps — reflecting the shorter, more varied fiber typical of woolen processing.', 1, '{"condenser","woolen-system"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is a key structural/process difference between the ''woolen'' and ''worsted'' spinning systems for wool fiber?', '["Worsted processing includes combing (to align long fibers and remove short ones), while woolen processing uses shorter/mixed-length fiber without combing, producing a fuzzier, bulkier yarn","Woolen and worsted are simply two different names for the identical process with zero differences","Worsted processing never uses any carding step, only woolen does","Woolen yarn is always stronger and smoother than worsted yarn"]'::jsonb, 'Worsted processing includes combing (to align long fibers and remove short ones), while woolen processing uses shorter/mixed-length fiber without combing, producing a fuzzier, bulkier yarn', 'Worsted spinning uses longer wool fibers, includes a combing step for fiber alignment and short-fiber removal (similar in principle to cotton combing), yielding smooth, strong, compact yarn; woolen spinning skips combing and uses shorter/more varied fiber, producing a bulkier, fuzzier, softer yarn.', 2, '{"woolen-vs-worsted"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What does ''air-jet spinning'' (a distinct method from rotor/open-end spinning) use to insert twist-like cohesion into the yarn?', '["Compressed air vortices that wrap outer fibers around a core of parallel fibers, creating a yarn structure without true mechanical twist insertion","A traditional ring-and-traveler mechanism identical to ring spinning","A rotor that physically twists fiber via centrifugal rotation, identical to rotor spinning","Hand-twisting performed by an operator at each spinning position"]'::jsonb, 'Compressed air vortices that wrap outer fibers around a core of parallel fibers, creating a yarn structure without true mechanical twist insertion', 'Air-jet (vortex-style) spinning uses swirling compressed-air vortices to wrap a portion of the fiber strand''s outer fibers around a largely untwisted parallel-fiber core, creating yarn cohesion through this wrapping action rather than conventional mechanical twist.', 2, '{"air-jet-spinning"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is a general advantage of air-jet (vortex) spinning over ring spinning in terms of production speed?', '["Air-jet spinning can achieve much higher yarn delivery speeds since it doesn''t rely on the mechanical limitations of a rotating ring-traveler system","Air-jet spinning is always slower than ring spinning under every condition","Speed is identical between the two methods with no meaningful difference","Air-jet spinning cannot produce yarn continuously, only ring spinning can"]'::jsonb, 'Air-jet spinning can achieve much higher yarn delivery speeds since it doesn''t rely on the mechanical limitations of a rotating ring-traveler system', 'Since air-jet spinning doesn''t depend on a physically rotating traveler (whose speed is limited by heat/wear/centrifugal force), it can run at substantially higher yarn delivery speeds than ring spinning, though the resulting yarn has different (often lower-strength, different-handle) characteristics suited to specific end uses.', 2, '{"air-jet-spinning","production-speed"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What does ''compact spinning'' (an enhancement to conventional ring spinning) primarily aim to improve?', '["It condenses the fiber strand immediately after drafting (before twist insertion) using suction, reducing hairiness and improving yarn evenness/strength","It eliminates the need for any drafting process before spinning","It replaces the traveler with a fully different open-end mechanism","It only affects the dyeing properties of the finished yarn"]'::jsonb, 'It condenses the fiber strand immediately after drafting (before twist insertion) using suction, reducing hairiness and improving yarn evenness/strength', 'Compact spinning adds a suction-based condensing zone right after the front drafting rollers, pulling stray/floating fibers into a narrower, more compact strand just before twist is inserted — this reduces hairiness and improves strength/evenness compared to conventional ring spinning.', 2, '{"compact-spinning"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why does compact spinning generally produce yarn with LESS hairiness than conventional ring spinning of the same count?', '["The suction-based condensing step gathers fiber ends more tightly into the strand before twist is applied, leaving fewer loose protruding fiber ends","Compact spinning uses zero twist, eliminating hairiness entirely by definition","Hairiness is determined solely by fiber type and has no relationship to the spinning method used","Compact spinning always uses much coarser fiber than conventional ring spinning"]'::jsonb, 'The suction-based condensing step gathers fiber ends more tightly into the strand before twist is applied, leaving fewer loose protruding fiber ends', 'By narrowing/condensing the fiber strand via suction immediately before twist insertion, compact spinning ensures more fiber ends are captured within the twisted structure rather than left protruding loosely — directly reducing yarn hairiness compared to conventional ring spinning''s wider, less-controlled pre-twist zone.', 2, '{"compact-spinning","hairiness"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the primary reason synthetic filament yarns (like continuous polyester or nylon) do not require the same spinning preparatory sequence (carding, drawing, roving) as staple cotton fiber?', '["Filament yarns are extruded as continuous, already-uniform strands from molten/dissolved polymer, so there are no short discrete fibers needing to be aligned, cleaned, and drafted together","Filament yarns are actually processed through an identical carding and roving sequence as cotton, with no differences","Filament fiber cannot be spun into yarn at all without first being cut into staple lengths","Synthetic filament production has no relationship to the concept of fiber length at all"]'::jsonb, 'Filament yarns are extruded as continuous, already-uniform strands from molten/dissolved polymer, so there are no short discrete fibers needing to be aligned, cleaned, and drafted together', 'Unlike staple fibers (which are short and must be opened, cleaned, aligned, and drafted together via carding/drawing/roving), synthetic filaments are extruded directly as continuous, uniform strands — bypassing the entire staple-fiber preparatory sequence, though filament may later be textured or cut into staple form for blending with natural fibers.', 2, '{"filament-vs-staple"}'::text[]);
